"""Read queries using caller-owned SQLite connections and transactions."""

import sqlite3
from typing import Any


def fetch_clients(
    connection: sqlite3.Connection, *, limit: int = 100, offset: int = 0
) -> list[Any]:
    """Return a bounded batch of clients using the connection's row factory.

    Row order is unspecified. The caller owns the connection and transaction.
    """
    if isinstance(limit, bool) or not isinstance(limit, int) or limit < 1:
        raise ValueError("limit must be a positive integer")
    if isinstance(offset, bool) or not isinstance(offset, int) or offset < 0:
        raise ValueError("offset must be a non-negative integer")

    cursor = connection.execute("SELECT * FROM clients LIMIT ? OFFSET ?", (limit, offset))
    try:
        return cursor.fetchall()
    finally:
        cursor.close()
